class _PigeonCodec extends StandardMessageCodec {
  const _PigeonCodec();
  @override
  void writeValue(WriteBuffer buffer, Object? value) {
    if (value is int) {
      buffer.putUint8(4);
      buffer.putInt64(value);
    }    else if (value is DPoPModeMessage) {
      buffer.putUint8(129);
      writeValue(buffer, value.index);
    }    else if (value is FlowStepKind) {
      buffer.putUint8(130);
      writeValue(buffer, value.index);
    }    else if (value is AnswerKind) {
      buffer.putUint8(131);
      writeValue(buffer, value.index);
    }    else if (value is ConfigureMessage) {
      buffer.putUint8(132);
      writeValue(buffer, value.encode());
    }    else if (value is LoginParametersMessage) {
      buffer.putUint8(133);
      writeValue(buffer, value.encode());
    }    else if (value is ChallengeMessage) {
      buffer.putUint8(134);
      writeValue(buffer, value.encode());
    }    else if (value is CredentialsMessage) {
      buffer.putUint8(135);
      writeValue(buffer, value.encode());
    }    else if (value is RedirectToWebMessage) {
      buffer.putUint8(136);
      writeValue(buffer, value.encode());
    }    else if (value is FlowStepMessage) {
      buffer.putUint8(137);
      writeValue(buffer, value.encode());
    }    else if (value is FormFieldMessage) {
      buffer.putUint8(138);
      writeValue(buffer, value.encode());
    }    else if (value is AnswerMessage) {
      buffer.putUint8(139);
      writeValue(buffer, value.encode());
    }    else if (value is SavedPasswordMessage) {
      buffer.putUint8(140);
      writeValue(buffer, value.encode());
    }    else if (value is RegisteredPasskeyMessage) {
      buffer.putUint8(141);
      writeValue(buffer, value.encode());
    }    else if (value is PushEnrollmentMessage) {
      buffer.putUint8(142);
      writeValue(buffer, value.encode());
    }    else if (value is PendingApprovalMessage) {
      buffer.putUint8(143);
      writeValue(buffer, value.encode());
    }    else if (value is PushNotificationMessage) {
      buffer.putUint8(144);
      writeValue(buffer, value.encode());
    }    else if (value is FlowLogMessage) {
      buffer.putUint8(145);
      writeValue(buffer, value.encode());
    } else {
      super.writeValue(buffer, value);
    }
  }

  @override
  Object? readValueOfType(int type, ReadBuffer buffer) {
    switch (type) {
      case 129:
        final value = readValue(buffer) as int?;
        return value == null ? null : DPoPModeMessage.values[value];
      case 130:
        final value = readValue(buffer) as int?;
        return value == null ? null : FlowStepKind.values[value];
      case 131:
        final value = readValue(buffer) as int?;
        return value == null ? null : AnswerKind.values[value];
      case 132:
        return ConfigureMessage.decode(readValue(buffer)!);
      case 133:
        return LoginParametersMessage.decode(readValue(buffer)!);
      case 134:
        return ChallengeMessage.decode(readValue(buffer)!);
      case 135:
        return CredentialsMessage.decode(readValue(buffer)!);
      case 136:
        return RedirectToWebMessage.decode(readValue(buffer)!);
      case 137:
        return FlowStepMessage.decode(readValue(buffer)!);
      case 138:
        return FormFieldMessage.decode(readValue(buffer)!);
      case 139:
        return AnswerMessage.decode(readValue(buffer)!);
      case 140:
        return SavedPasswordMessage.decode(readValue(buffer)!);
      case 141:
        return RegisteredPasskeyMessage.decode(readValue(buffer)!);
      case 142:
        return PushEnrollmentMessage.decode(readValue(buffer)!);
      case 143:
